// SCHICHT 0 | Architekturbezug: Kap. 4.2 Eingang
// Normalisiert den Request, startet die Latenzmessung (Kap. 4.2 [5c])
// und validiert die Eingabe.
//
// NEU ggü. v2: Laengenbegrenzung. Die Anfrage fliesst in bis zu vier
// LLM-Prompts; eine unbegrenzte Eingabe ist sowohl ein Kontextfenster-
// Risiko (Kap. 4.6.1) als auch eine Prompt-Injection-Flaeche gegen die
// Anti-Halluzinations-Direktive.
const body = $json.body || $json;
const raw = (body.query || '').toString().trim();

// NF-08 Mehrsprachigkeit ("Antwortsprache = Anfragesprache in 100 % der
// Faelle") und UC-01 A5 (nicht unterstuetzte Sprache -> Meldung).
// Regelbasiert statt per LLM: Die Detektion sitzt VOR der Klassifikation
// im kritischen Pfad; ein zusaetzlicher LLM-Aufruf kostete ~1 s und
// damit ein Fuenftel des NF-03-Budgets. Portiert aus
// petra_hybrid/language.py::detect_language.
function detectLanguage(text) {
  const t = (text || '').trim();
  if (!t) return { language: 'Deutsch', supported: true, reason: 'Leere Anfrage.' };
  const nonLatin = (t.match(/[Ѐ-ӿ֐-׿؀-ۿͰ-Ͽ一-鿿぀-ヿ]/g) || []).length;
  if (nonLatin >= 3 && nonLatin / t.length > 0.15) {
    return { language: 'unbekannt', supported: false, reason: 'Nicht-lateinische Schrift erkannt.' };
  }
  const DE = ['welche','welcher','welches','wie','was','ist','hat','der','die','das','und','oder','für','mit','von','kostet','vergleiche','unterschied','eignet','sich','bei','kann','nicht','ein','eine','einen','zwischen'];
  const EN = ['which','what','how','is','are','has','have','the','and','or','for','with','of','cost','costs','compare','difference','between','suitable','can','not','a','an','does','do','price'];
  const tokens = (t.toLowerCase().match(/[a-zA-ZäöüßÄÖÜ]+/g) || []);
  let de = tokens.filter(x => DE.includes(x)).length;
  const en = tokens.filter(x => EN.includes(x)).length;
  if (/[äöüßÄÖÜ]/.test(t)) de += 2;
  if (de + en === 0) return { language: 'Deutsch', supported: true, reason: 'Keine Sprachmarker; Standardsprache.' };
  return de >= en
    ? { language: 'Deutsch', supported: true, reason: `${de} DE vs ${en} EN Marker.` }
    : { language: 'Englisch', supported: true, reason: `${en} EN vs ${de} DE Marker.` };
}

if (!raw) {
  return [{ json: {
    __input_invalid: true,
    error: 'Leere Anfrage. Feld "query" ist erforderlich.',
    start_ts: Date.now()
  }}];
}

return [{
  json: {
    query: raw.slice(0, 1000),
    query_truncated: raw.length > 1000,
    language: body.language || detectLanguage(raw).language,
    language_supported: detectLanguage(raw).supported,
    language_reason: detectLanguage(raw).reason,
    top_k: Math.min(Math.max(parseInt(body.top_k) || 5, 1), 10),
    score_threshold: typeof body.score_threshold === 'number' ? body.score_threshold : parseFloat($env.PETRA_CRAG_THRESHOLD || '0.65'),
    request_id: body.request_id
      || ($json.headers && $json.headers['x-request-id'])
      || (Date.now() + '-' + Math.random().toString(36).slice(2)),
    retrieval_round: 1,
    activated_paths: [],
    start_ts: Date.now()
  }
}];

return [{ json: {
  answer: 'Die Anfrage konnte nicht verarbeitet werden.',
  context_sufficient: false,
  sources: [],
  retrieved_documents: 0,
  verified: false,
  fallback_reason: $json.error || 'Ungueltige Eingabe.',
  latency_ms: Date.now() - ($json.start_ts || Date.now())
}}];

// UC-01 A5: "Anfrage in nicht unterstuetzter Sprache -> System
// versucht automatische Erkennung; bei Misserfolg: Fehlermeldung."
// NF-08 begrenzt den Support auf Deutsch und Englisch.
//
// Es wird bewusst KEIN Uebersetzungsversuch unternommen: Das
// Embedding-Modell deckt nur DE/EN zuverlaessig ab (Kap. 4.6.1,
// Mehrsprachigkeits-Grenze). Eine uebersetzte Anfrage wuerde ein
// Retrieval-Ergebnis liefern, dessen Qualitaet niemand beurteilen kann —
// eine ehrliche Meldung ist die belastbarere Antwort.
return [{ json: {
  answer: 'Diese Anfrage scheint in einer nicht unterstuetzten Sprache verfasst zu sein. Das System beantwortet Anfragen auf Deutsch und Englisch. Bitte formulieren Sie die Frage in einer dieser Sprachen.',
  query_class: 'nicht_unterstuetzte_sprache',
  context_sufficient: false,
  sources: [],
  retrieved_documents: 0,
  verified: false,
  fallback_reason: $json.language_reason || 'Sprache nicht unterstuetzt (NF-08).',
  latency_ms: Date.now() - ($json.start_ts || Date.now()),
  request_id: $json.request_id
}}];

// SCHICHT 1c | Kap. 4.2 [1c]
// Vereinheitlicht das Ergebnis des Cache-Lookups und stellt den
// Anfragekontext wieder her (der HTTP-Node verliert ihn).
const ctx = $('Input normalisieren').last().json;
const res = $json || {};
const hit = res.cache_hit === true && res.payload;

return [{ json: {
  ...ctx,
  cache_hit: !!hit,
  cache_age_seconds: res.cache_age_seconds || 0,
  cached_payload: hit ? res.payload : null
}}];

// Kap. 3.1.1: CAG ist eine reine Latenzschicht - die Antwort ist
// inhaltlich identisch zur regulaeren Pipeline. Kennzeichnung als
// Cache-Antwort bleibt aber erhalten (P6 Erklaerbarkeit): Der Nutzer
// muss erkennen koennen, dass die Antwort nicht neu erzeugt wurde.
const payload = $json.cached_payload || {};
return [{ json: {
  ...payload,
  cache_hit: true,
  cache_age_seconds: $json.cache_age_seconds,
  latency_ms: Date.now() - ($json.start_ts || Date.now()),
  request_id: $json.request_id
}}];

// SCHICHT 1 | Kap. 4.2 [1], Kap. 4.3 [1]
//
// SINGLE SOURCE OF TRUTH fuer das Routing. Portiert aus
// petra_hybrid/classification.py::ROUTING_MATRIX. In v2 lag dieses
// Wissen an drei Stellen (Classifier-Kategorien, fuenf Set-Nodes,
// Switch-Regeln) und lief bei der Restklasse auseinander - die Anfrage
// landete in einem Dead End (Review P-01).
//
// NEU - KLASSIFIKATIONSKORREKTUR (Evaluation 17.08.2026):
// Der Testlauf ueber die 50 Weidmueller-Testfaelle ergab eine
// Dokument-Trefferquote von nur 32 %. Die Auswertung nach Fragetyp
// zeigte kein Muster; auffaellig war stattdessen, dass die Klasse bei
// Produktfragen mit Klartextnamen ("Wie hoch ist der Nennstrom der
// WDU 2.5?") systematisch auf 'allgemeine_technische_frage' fiel,
// obwohl die Produktextraktion den Code korrekt erkannte
// (candidate_products: ["WDU 2.5"]).
//
// Die Folge war dreifach:
//   - tag:false            -> der TAG-Pfad blieb ungenutzt
//   - hyde:true            -> ein unnoetiger LLM-Aufruf
//   - CLASS_HINT Q5        -> "begrifflich/konzeptuell, ohne
//                             Produktempfehlung" im Prompt, also genau
//                             die falsche Anweisung fuer eine
//                             Attributabfrage
//
// Die Korrektur unten ist regelbasiert und damit deterministisch: Wer
// einen Produktcode nennt, stellt keine Restklassen-Frage. Dieselbe
// Logik nutzt der Workflow bereits im heuristischen Fallback des
// Text Classifiers; sie wird hier nur konsequent auch auf das
// LLM-Ergebnis angewendet.

const ROUTING = {
  produktspezifikation:       { q_class:'Q1', dense:true, bm25:true, tag:true,  hyde:false, agentic:false },
  produktvergleich:           { q_class:'Q2', dense:true, bm25:true, tag:true,  hyde:false, agentic:false, dual_retrieval:true },
  produktsuche:               { q_class:'Q3', dense:true, bm25:true, tag:false, hyde:true,  agentic:false },
  preisanfrage:               { q_class:'Q4', dense:true, bm25:true, tag:false, hyde:false, agentic:true  },
  allgemeine_technische_frage:{ q_class:'Q5', dense:true, bm25:true, tag:false, hyde:false, agentic:false, fallback:true }  // s5: Kap. 4.2 [1a] HyDE nur Q3
};
const FALLBACK = 'allgemeine_technische_frage';

const raw = $json.query_class;
const known = Object.prototype.hasOwnProperty.call(ROUTING, raw);

// `let` statt `const`: Die Klasse kann unten durch die
// Produktcode-Erkennung noch korrigiert werden.
let klasse = known ? raw : FALLBACK;

// --- Produktcode-Erkennung (Kap. 4.1.1, Review P-12) ---------------
// Whitelist realer Formate statt generischer Heuristik. Das alte Muster
// verlangte einen Buchstabenpraefix und verfehlte reine Artikelnummern
// wie 2903590000; gleichzeitig matchte es IP67/ATEX/DIN als Produkte.
// NEU (2026-09-13): Bindestrich-Kompositum-Muster ergaenzt. Fund:
// "HDC-KIT-HA 10.110" und "UR20-FBC-PN-IRT-V2" (haeufige Weidmueller-
// Bauform bei Steckverbindern/Kopplern) wurden von den bisherigen vier
// Mustern nur fragmentarisch erkannt ("HA 10" bzw. "UR20") - die fuer
// die Unterscheidung von Geschwister-Varianten entscheidende Endung
// ging verloren. Folge: Retrieval/Priorisierung konnte
// "UR20-FBC-PN-IRT-V2" nicht von "UR20-FBC-EIP" unterscheiden
// (Testfaelle 34, 36, 58, 59 - falsches Geschwisterprodukt geliefert).
// Das neue Muster erfasst den GESAMTEN Bindestrich-/Leerzeichen-Code ab
// einem Buchstaben-Anker, inkl. Ziffern und Punkten in den Segmenten.
// ERWEITERT (2026-09-13): Zeichenklasse um +, / und Komma ergaenzt.
// Fund: Weidmueller-Codes fuer Ueberspannungsschutz/Leiterplattenklemmen
// nutzen diese Zeichen INNERHALB des Codes als Bedeutungstraeger (z.B.
// "3+1" = Polkonfiguration, "300/12,5" = Ratingpaar). Die vorherige
// Version brach genau an diesen Zeichen ab (Testfaelle 25, 26, 51, 52)
// und verlor damit exakt den Teil, der Geschwistervarianten unterscheidet.
const PATTERNS = [
  /\b\d{10}\b/g,                              // reine Artikelnummer
  /\b[A-Z]{1,3}\d[A-Z]?\d{2,5}[A-Z]?\b/g,     // z.B. O1D302, A2C 4
  /\b[A-Z]{2,4}\s?\d{2,6}[A-Z]?\b/g,          // z.B. BOS 0035, TRS 24
  /\b[A-Z]{2,4}\s?\d{1,2}\.\d{1,2}\b/g,        // z.B. WDU 2.5, A2C 2.5
  /\b[A-Z]{2,4}\s?\d{1,2}[A-Z]?\/\d{1,3}\b/g,  // z.B. ZQV 4N/10, WQV 4/2
  /\b[A-Z][A-Z0-9]{1,6}(?:[-\s][A-Z0-9.,+\/]+){1,8}\b/g    // NEU: HDC-KIT-HA 10.110, UR20-FBC-PN-IRT-V2
];

// Normbezeichnungen und Schnittstellen, die wie Produktcodes aussehen,
// aber keine sind. Ohne diese Liste wuerde "IP67" oder "M12" eine
// Produktfilterung ausloesen, die ins Leere laeuft.
const NON_PRODUCT = ['IP','ATEX','DIN','EN','ISO','IEC','SIL','NEMA','UL','VDE','PL','IO','USB','RS','DC','AC','PNP','NPN','M12','M8'];
const NON_PRODUCT_EXACT = ['IO-LINK','IOLINK','PROFINET','ETHERCAT','MODBUS'];

const q = $json.query || '';
const found = [];
for (const re of PATTERNS) {
  for (const m of (q.match(re) || [])) {
    const token = m.trim();
    const upper = token.toUpperCase().replace(/\s/g, '');
    if (NON_PRODUCT_EXACT.includes(upper)) continue;
    const letters = upper.replace(/[^A-Z]/g, '');
    if (letters && NON_PRODUCT.includes(letters)) continue;
    if (!/\d/.test(upper)) continue;
    found.push(token);
  }
}
const unique = [...new Set(found)];

// Fragment-Bereinigung: entfernt Kandidaten, die Teilstring eines
// LAENGEREN Kandidaten sind.
const norm = s => s.toUpperCase().replace(/\s/g, '');
const candidate_products = unique.filter(p =>
  !unique.some(other => other !== p && norm(other).includes(norm(p)) && norm(other).length > norm(p).length)
);

// Korrektur nach ANZAHL erkannter Produkte, unabhaengig davon, was der
// Text Classifier selbst geraten hat. Fund 13.09.2026: Der Classifier
// riet bei einer eindeutigen Einzelprodukt-Frage ("Klippon POK 080806")
// und bei einer reinen Produktsuch-Frage ("Ich brauche eine...") jeweils
// direkt "produktvergleich" - eine Korrektur, die nur bei der Restklasse
// ansetzt, laesst solche direkten Classifier-Fehlgriffe unkorrigiert.
const SUCH_WOERTER = ['brauche', 'suche', 'empfehl', 'geeignet für', 'geeignet fuer', 'welches produkt'];
const klasse_vor_korrektur = klasse;
if (klasse !== 'preisanfrage') {
  if (candidate_products.length >= 2) {
    klasse = 'produktvergleich';
  } else if (candidate_products.length === 1) {
    klasse = 'produktspezifikation';
  } else if (SUCH_WOERTER.some(w => q.toLowerCase().includes(w))) {
    klasse = 'produktsuche';
  }
  // 0 Kandidaten, kein Suchwort: Classifier-Entscheidung unveraendert.
}

const r = ROUTING[klasse];

// --- Aktivierte Retrieval-Pfade ------------------------------------
const paths = [];
if (r.dense) paths.push('dense');
if (r.bm25) paths.push('bm25');
if (r.tag) paths.push('tag');
if (r.agentic) paths.push('agentic');
if (r.hyde) paths.push('hyde_eligible');

return [{ json: { ...$json,
  query_class: klasse,
  q_class: r.q_class,
  routing_fallback_applied: !known,
  // Nachvollziehbarkeit (P6): In der Telemetrie sichtbar, wie oft die
  // Korrektur greift. Ein hoher Wert ist ein Hinweis darauf, dass die
  // Kategorienbeschreibung des Text Classifiers nachgeschaerft werden
  // sollte - die Korrektur behandelt das Symptom, nicht die Ursache.
  klasse_korrigiert: klasse !== klasse_vor_korrektur,
  klasse_vor_korrektur,
  tag_index_aktiv: !!r.tag,
  // s5: kein HyDE bei Artikelnummer oder Zahl+Einheit (Akarsu et al. 2026)
  hyde_eligible: !!r.hyde && !/\b\d{10}\b/.test(q)
    && !/\d+(?:[.,]\d+)?\s*(mm²|mm2|mm|kV|mV|V|mA|kA|A|kW|W|Hz|°C|kg|g|Nm|Ω|%|ms|AWG)(?![A-Za-zÄÖÜäöüß])/.test(q),
  agentic_pfad: !!r.agentic,
  dual_retrieval: !!r.dual_retrieval && candidate_products.length >= 2,
  candidate_products,
  activated_paths: paths
}}];

// SCHICHT 2 Einstieg | Kap. 4.2 Schicht 2
//
// EINZIGER Einstiegspunkt ins Retrieval. Runde 1 kommt von
// 'Routing & Produktextraktion', Runde 2 von 'Runde 2 vorbereiten'.
// Hier werden die Query-Varianten gebaut: Jeder Retriever bekommt die
// Textform, die zu seinem Suchverfahren passt.
//
// HARTER LOOP-GUARD (Review P-06): In v2 wurde retrieval_round aus
// einer Node-Referenz rekonstruiert und dabei auf 1 zurueckgesetzt -
// eine potentiell endlose Rewrite-Schleife, die pro Zyklus einen
// LLM-Call und damit die GPU belegte. Der Zaehler wird jetzt
// durchgereicht und hier hart begrenzt.
const round = Math.min(parseInt($json.retrieval_round) || 1, 2);
const original = ($json.query_original || $json.query || '').trim();
const rewritten = ($json.query_rewritten || '').trim();
const hyde = ($json.hyde_document || '').trim();
const codes = $json.candidate_products || [];

// BM25 (lexikalisch): IMMER die unveraenderte Anfrage plus erkannte
// Produktcodes zur Gewichtsverstaerkung. KEIN Rewriting - Synonyme
// zerstoeren den exakten Code-Match, der die Staerke von BM25 ist
// (Kap. 4.5.1, Achse 1). Produktcodes werden ANGEHAENGT, nicht
// ersetzt (Review P-11): Sonst geht der Attributbegriff verloren und
// BM25 liefert irgendeinen Chunk des Produkts statt des richtigen.
//const query_sparse = [original, "Klemme", "Reihenklemme", ...codes].join(' ').trim();

// Die pauschale Term-Injektion verfaelscht BM25 bei Nicht-Klemmen-Produkten
// (Fall 17 Netzteil, 40 Switch, 22 Ableiter). Nur bei erkannter
// Klemmen-Produktfamilie anhaengen.
const KLEMMEN_PREFIX = /^(WDU|WDK|ZDU|IDU|A2C|ADT|WAP|WEW|WQV|ZQV)/i;
const istKlemme = codes.some(c => KLEMMEN_PREFIX.test(c));
const query_sparse = [original, ...(istKlemme ? ['Reihenklemme'] : []), ...codes]
  .join(' ').trim();

// Dense (semantisch): HyDE-Dokument > Rewrite > Original.
// Kap. 4.3 [1a]: Das hypothetische Snippet ERSETZT die Anfrage als
// Embedding-Basis.
const query_dense = hyde || rewritten || original;

// TAG (serialisierte Tabellenzeilen): Produktcodes + Attributbegriffe
// statt Fragesatz - Tabellenzeilen enthalten keine Fragen.
const query_tag = codes.length
  ? [...codes, 'Technische Daten Spezifikation'].join(' ')
  : original;

return [{ json: { ...$json,
  query: original,
  query_original: original,
  query_rewritten: rewritten || null,
  hyde_document: hyde || null,
  query_sparse,
  query_dense,
  query_tag,
  retrieval_round: round
}}];

// Kap. 4.3 [1a]: Das hypothetische Snippet ersetzt die Anfrage als
// Embedding-Basis fuer Dense Retrieval. BM25 und TAG bleiben
// unveraendert - fuer lexikalische Suche waere ein generierter Text
// kontraproduktiv.
const ctx = $('Retrieval-Start').last().json;
const doc = ($json.text || $json.output || '').trim();
return [{ json: { ...ctx,
  hyde_document: doc || null,
  query_dense: doc || ctx.query_dense,
  activated_paths: [...(ctx.activated_paths || []), doc ? 'hyde_applied' : 'hyde_failed']
}}];

// Vereinheitlicht das Ausgabeformat eines Retrieval-Pfads.
//
// KORREKTUR (Review P-02): v2 las `j.text || j.pageContent || j.document`.
// Der Chroma-Node liefert im load-Modus aber {document:{pageContent,
// metadata}, score} - `j.document` traf und lieferte ein OBJEKT statt
// eines Strings. Folge: '[object Object]' im Prompt, leere Metadaten und
// damit durchgaengig 'unbekannt' in der Quellenanzeige - ein Verstoss
// gegen P6 (Erklaerbarkeit) im gesamten Dense-Pfad.
// v3 deckt beide Verschachtelungen explizit ab und erzwingt Strings.
const SRC = 'dense';
const rows = [];

for (const [i, item] of $input.all().entries()) {
  const j = item.json || {};
  if (j.__skipped) continue;

  // Chroma: {document:{pageContent,metadata},score} | BM25: {results:[...]}
  const doc = (j.document && typeof j.document === 'object') ? j.document : j;
  const meta = doc.metadata || j.metadata || j.meta || {};

  let text = doc.pageContent ?? j.pageContent ?? j.text ?? '';
  if (typeof text !== 'string') text = '';

  // chunk_id MUSS quellenuebergreifend identisch sein, sonst kann RRF
  // keine Raenge kombinieren (Review P-03). Faellt sie aus, wird ein
  // INHALTS-Hash gebildet - eine quellenpraefixierte Ersatz-ID koennte
  // per Konstruktion nie kollidieren und macht die Dedup wirkungslos.
  let cid = j.chunk_id || j.id || meta.chunk_id;
  if (!cid) {
    const norm = text.trim().toLowerCase().replace(/\s+/g, ' ');
    let h = 0;
    for (let k = 0; k < norm.length; k++) { h = ((h << 5) - h + norm.charCodeAt(k)) | 0; }
    cid = (meta.source_type === 'table' ? 'tbl-' : 'txt-') + Math.abs(h).toString(16);
  }

  const score = typeof j.score === 'number' ? j.score
    : (typeof j.similarity === 'number' ? j.similarity : null);

  rows.push({ chunk_id: cid, text, metadata: meta, score, rank: rows.length + 1 });
}

return [{ json: { retrieval_source: SRC, results: rows, count: rows.length } }];

// Vereinheitlicht das Ausgabeformat eines Retrieval-Pfads.
//
// KORREKTUR (Review P-02): v2 las `j.text || j.pageContent || j.document`.
// Der Chroma-Node liefert im load-Modus aber {document:{pageContent,
// metadata}, score} - `j.document` traf und lieferte ein OBJEKT statt
// eines Strings. Folge: '[object Object]' im Prompt, leere Metadaten und
// damit durchgaengig 'unbekannt' in der Quellenanzeige - ein Verstoss
// gegen P6 (Erklaerbarkeit) im gesamten Dense-Pfad.
// v3 deckt beide Verschachtelungen explizit ab und erzwingt Strings.
const SRC = 'tag';
const rows = [];

for (const [i, item] of $input.all().entries()) {
  const j = item.json || {};
  if (j.__skipped) continue;

  // Chroma: {document:{pageContent,metadata},score} | BM25: {results:[...]}
  const doc = (j.document && typeof j.document === 'object') ? j.document : j;
  const meta = doc.metadata || j.metadata || j.meta || {};

  let text = doc.pageContent ?? j.pageContent ?? j.text ?? '';
  if (typeof text !== 'string') text = '';

  // chunk_id MUSS quellenuebergreifend identisch sein, sonst kann RRF
  // keine Raenge kombinieren (Review P-03). Faellt sie aus, wird ein
  // INHALTS-Hash gebildet - eine quellenpraefixierte Ersatz-ID koennte
  // per Konstruktion nie kollidieren und macht die Dedup wirkungslos.
  let cid = j.chunk_id || j.id || meta.chunk_id;
  if (!cid) {
    const norm = text.trim().toLowerCase().replace(/\s+/g, ' ');
    let h = 0;
    for (let k = 0; k < norm.length; k++) { h = ((h << 5) - h + norm.charCodeAt(k)) | 0; }
    cid = (meta.source_type === 'table' ? 'tbl-' : 'txt-') + Math.abs(h).toString(16);
  }

  const score = typeof j.score === 'number' ? j.score
    : (typeof j.similarity === 'number' ? j.similarity : null);

  rows.push({ chunk_id: cid, text, metadata: meta, score, rank: rows.length + 1 });
}

return [{ json: { retrieval_source: SRC, results: rows, count: rows.length } }];

// BM25-HTTP liefert genau ein Item: { results: [{chunk_id, text,
// metadata, score, rank}, ...] }. Bei Ausfall (onError=continue am
// HTTP-Node) fehlt `results` - dann wird eine leere, aber
// wohlgeformte Liste erzeugt, damit RRF und Merge weiterlaufen.
const input = $input.first().json || {};
const hits = Array.isArray(input.results) ? input.results : [];
const degraded = !Array.isArray(input.results);

const normalized = hits.map((hit, index) => ({
  chunk_id: hit.chunk_id ?? `txt-bm25-${index}`,
  text: typeof hit.text === 'string' ? hit.text : '',
  metadata: hit.metadata ?? {},
  score: Number(hit.score ?? 0),
  rank: Number(hit.rank ?? index + 1)
}));

return [{ json: {
  retrieval_source: 'bm25',
  results: normalized,
  count: normalized.length,
  degraded,
  warning: input.warning || (degraded ? 'BM25-Dienst nicht erreichbar - Pipeline laeuft ohne Sparse-Pfad weiter.' : null)
}}];

// Fuehrt die 1-4 Merge-Items zu EINEM Item zusammen und stellt den
// Anfragekontext wieder her (Chroma- und HTTP-Nodes verlieren ihn).
// `.last()` statt `.first()` (Review P-06, CRAG-Runde 2).
// s2 (Lexikon-Pfad): vierte Quelle 'product' + aufgeloeste Artikelnummern.
const ctx = $('Retrieval-Start').last().json;
const out = { dense_results: [], bm25_results: [], tag_results: [], product_results: [] };
const warnings = [];
let resolved = [], produktInfo = [], produktExakt = false;

for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.retrieval_source) continue;
  out[j.retrieval_source + '_results'] = j.results || [];
  if (j.warning) warnings.push(j.warning);
  if (j.retrieval_source === 'product') {
    resolved = j.resolved_artikelnummern || [];
    produktInfo = j.produkt_info || [];
    produktExakt = j.produkt_exakt === true;
  }
}

const total = out.dense_results.length + out.bm25_results.length
  + out.tag_results.length + out.product_results.length;
return [{ json: { ...ctx, ...out,
  resolved_artikelnummern: resolved,
  produkt_info: produktInfo,
  produkt_exakt: produktExakt,
  retrieval_warnings: warnings,
  retrieval_total: total
} }];

// SCHICHT 3a | Kap. 4.2 [3a], Kap. 4.3 [3a]
// RRF(d) = Sum_i 1/(k + rank_i(d)), k=50, Top-10. Portiert aus
// petra_hybrid/rrf.py (Version 2).
//
// NEU ggü. v2:
//  (1) bm25_normalized: Min-Max innerhalb der BM25-Liste. Der
//      CRAG-Filter braucht einen quellenuebergreifend vergleichbaren
//      Wert; der RRF-Score bleibt reines Ranking-Kriterium.
//  (2) ID-Konsistenz-Guard: Kommt keine chunk_id in mehr als einer
//      Quelle vor, kann RRF keine Raenge kombinieren und degeneriert
//      still zu einer Konkatenation. Genau dieser Qualitaetsverlust
//      war in v2 unsichtbar (Review P-03) - jetzt wird er gemessen und
//      als Warnung mitgefuehrt.
//
// KORREKTUR DES GUARDS 
// ---------------------------------------------
// Der Guard meldete in JEDER Anfrage 0 % und nannte als Ursache
// abweichende chunk_ids zwischen BM25-Index und ChromaDB. Beides wurde
// ueberprueft und trifft nicht zu:
//
//   (a) ID-Deckung: Eine gestreute Stichprobe des BM25-Index gegen
//       beide Collections ergab 300/300 bzw. 233/233 Treffer — also
//       100 % Deckung. Die IDs sind konsistent.
//
//   (b) Der Guard mass ueber ALLE drei Pfade das Maximum der
//       paarweisen Ueberschneidungen. Dense liest aber
//       petra_text_chunks, TAG liest petra_tag_chunks — zwei disjunkte
//       Mengen. Eine Ueberschneidung ist dort per Konstruktion
//       unmoeglich, nicht Ausdruck eines Fehlers.
//
// Gemessen wird deshalb nur noch zwischen Pfaden, die DENSELBEN Raum
// durchsuchen. BM25 fuehrt Text- und Tabellen-Chunks in einem Index
// (Stichprobe: 1943 text / 582 table) und ist damit die einzige
// sinnvolle Vergleichsgroesse fuer Dense.
//
// Der Guard bleibt aussagekraeftig: Eine 0 bedeutet weiterhin, dass RRF
// keine Raenge kombiniert. Nur die Ursache ist eine andere als die
// urspruenglich vermutete — lexikalische und semantische Suche
// reagieren bei strukturgleichen Datenblaettern auf unterschiedliche
// Signale und finden verschiedene Dokumente.

const k = 50;
const topK = 30;

const lists = {
  dense: ($json.dense_results || []).map((r, i) => ({ ...r, rank: r.rank || i + 1 })),
  bm25:  ($json.bm25_results  || []).map((r, i) => ({ ...r, rank: r.rank || i + 1 })),
  tag:   ($json.tag_results   || []).map((r, i) => ({ ...r, rank: r.rank || i + 1 })),
  product: ($json.product_results || []).map((r, i) => ({ ...r, rank: r.rank || i + 1 }))  // s2
};

// --- BM25-Normalisierung (siehe petra_hybrid/scoring.py) -----------
const bm25Norm = {};
const bmScores = lists.bm25.map(r => Number(r.score) || 0);
if (bmScores.length) {
  const top = Math.max(...bmScores);
  const lo  = Math.min(...bmScores);
  const span = (top - lo) || 1;
  // Vertrauensdaempfung: Eine Liste aus lauter Zufallstreffern soll
  // ihren besten Zufallstreffer nicht auf 1.0 heben.
  const cap = Math.min(1, top / 6);
  lists.bm25.forEach((r, i) => {
    const rel = bmScores.length > 1 ? (bmScores[i] - lo) / span : 1;
    bm25Norm[r.chunk_id] = Math.max(0, Math.min(1, rel * cap));
  });
}

// --- Gewichtung der Quellen (70/30) ---
// Unweighted RRF (Cormack et al. 2009). Bei Gewichtung UND null
// Chunk-Ueberschneidung degeneriert die Formel zu einer Rangstrafe pro
// Liste: BM25-Rang 1 (0.3/51 = 0.00588) lag unter Dense-Rang 10
// (0.7/60 = 0.01167) — BM25 kam damit strukturell nie in die Top-10.
// Belegt: der BM25-Index findet 1020000000 mit Score 13.8, der Chunk
// erreichte den Prompt trotzdem nie (Faelle 10, 21, 43).
// Die Qualitaetsauswahl trifft der Cross-Encoder, nicht die Fusion.
const denseWeight = 0.6;
const bm25Weight  = 0.4;
const tagWeight   = 0.7;

const rrf = {};
const byId = {};
for (const [source, items] of Object.entries(lists)) {
  // Bestimme das Gewicht basierend auf der Quelle
  let sourceWeight = 1;
  if (source === 'dense') sourceWeight = denseWeight;
  else if (source === 'bm25') sourceWeight = bm25Weight;
  else if (source === 'tag') sourceWeight = tagWeight;
  else if (source === 'product') sourceWeight = 1.0;   // s2 (Lexikon-Pfad)

  for (const item of items) {
    const cid = item.chunk_id;
    if (!cid) continue;
    // Gewichtete RRF-Formel
    rrf[cid] = (rrf[cid] || 0) + sourceWeight * (1 / (k + item.rank));

    if (!byId[cid]) {
      byId[cid] = { chunk_id: cid, text: item.text || '', metadata: item.metadata || {}, source_scores: {}, sources: [] };
    }
    byId[cid].source_scores[source] = item.score;
    if (!byId[cid].sources.includes(source)) byId[cid].sources.push(source);
    if (!byId[cid].text && item.text) byId[cid].text = item.text;
    if (source === 'bm25' && bm25Norm[cid] !== undefined) {
      byId[cid].bm25_normalized = Math.round(bm25Norm[cid] * 1e4) / 1e4;
    }
  }
}

// --- Konsistenz-Guard (korrigiert) ---------------------------------
// Nur Dense gegen BM25: beide koennen dieselben Text-Chunks liefern.
// TAG bleibt aussen vor, weil es eine andere Collection durchsucht.
const denseIds = new Set(lists.dense.map(r => r.chunk_id).filter(Boolean));
const bm25Ids  = new Set(lists.bm25.map(r => r.chunk_id).filter(Boolean));

let consistency = 1;      // 1 = nicht messbar (nur ein Pfad aktiv)
let messbar = false;
if (denseIds.size && bm25Ids.size) {
  messbar = true;
  const inter = [...denseIds].filter(x => bm25Ids.has(x)).length;
  const kleiner = Math.min(denseIds.size, bm25Ids.size) || 1;
  consistency = Math.round((inter / kleiner) * 1e4) / 1e4;
}

// Zusaetzlich als Diagnosewert: Wie viele Dokumente teilen sich die
// beiden Pfade? Eine Ueberschneidung auf Dokumentebene bei null
// Ueberschneidung auf Chunkebene ist ein Hinweis auf zu feines oder
// inhaltlich inkohaerentes Chunking — die Pfade finden dann dasselbe
// Dokument, aber verschiedene Abschnitte daraus.
function dokumente(items) {
  return new Set(items
    .map(r => (r.metadata || {}).filename || String(r.chunk_id || '').split('_p')[0])
    .filter(Boolean));
}
const denseDocs = dokumente(lists.dense);
const bm25Docs  = dokumente(lists.bm25);
const docOverlap = denseDocs.size && bm25Docs.size
  ? [...denseDocs].filter(x => bm25Docs.has(x)).length
  : 0;

const warnings = [...($json.retrieval_warnings || [])];
if (messbar && consistency === 0) {
  warnings.push(
    `RRF-Ueberschneidung 0 %: Dense und BM25 liefern keine gemeinsamen `
    + `chunk_ids; RRF reiht die Listen aneinander statt Raenge zu `
    + `kombinieren. Gemeinsame Dokumente: ${docOverlap}. Die chunk_ids `
    + `selbst sind konsistent (geprueft: 100 % Deckung BM25-Index gegen `
    + `ChromaDB) — die Ursache liegt darin, dass lexikalische und `
    + `semantische Suche bei strukturgleichen Datenblaettern auf `
    + `unterschiedliche Signale reagieren.`
  );
}

// --- RRF-Sortierung ---
const sorted = Object.keys(rrf)
  .sort((a, b) => rrf[b] - rrf[a])
  .map(cid => ({ ...byId[cid], rrf_score: Math.round(rrf[cid] * 1e6) / 1e6 }));

// --- BM25-Mindestquote (5 Chunks) ---
// Verhindert, dass BM25 bei 0 % Chunk-Überschneidung strukturell
// aus dem Kandidatenfeld verschwindet.
const MIN_BM25 = 5;
let top = sorted.slice(0, topK);

// Prüfen, ob bereits genug BM25-Chunks in den Top-K enthalten sind
const bm25InTop = top.filter(c => c.sources && c.sources.includes('bm25')).length;
const fehlend = MIN_BM25 - bm25InTop;

if (fehlend > 0) {
  // Nachrücker: BM25-Chunks außerhalb der Top-K, die noch nicht in top sind
  const nachruecker = sorted.slice(topK)
    .filter(c => c.sources && c.sources.includes('bm25') && !top.some(t => t.chunk_id === c.chunk_id))
    .slice(0, fehlend);

  if (nachruecker.length > 0) {
    // Ersetze die letzten `nachruecker.length` Chunks in `top`
    // (das sind die mit den niedrigsten RRF-Scores) durch die Nachrücker.
    top.splice(top.length - nachruecker.length, nachruecker.length, ...nachruecker);
    // Hinweis: Die Reihenfolge ist nicht mehr strikt nach RRF, aber
    // der Cross-Encoder wird später neu bewerten – das ist akzeptabel.
  }
}

// s2 (Lexikon-Pfad): Produkt-Mindestquote. Chunks aus dem Datenblatt der
// aufgeloesten Artikelnummer duerfen nicht von Varianten-Datenblaettern aus
// dem Kandidatenfeld verdraengt werden; der Cross-Encoder entscheidet danach.
const MIN_PRODUCT = 6;
const prodInTop = top.filter(c => (c.sources || []).includes('product')).length;
const prodFehlend = MIN_PRODUCT - prodInTop;
if (prodFehlend > 0) {
  const prodNach = sorted
    .filter(c => (c.sources || []).includes('product') && !top.some(t => t.chunk_id === c.chunk_id))
    .slice(0, prodFehlend);
  if (prodNach.length) top = [...prodNach, ...top.slice(0, top.length - prodNach.length)];
}

const fused = top; // Fertige Top-K-Liste mit garantierter BM25-Mindestquote

return [{ json: { ...$json,
  fused_chunks: fused,
  id_consistency: consistency,
  id_consistency_messbar: messbar,
  doc_overlap_dense_bm25: docOverlap,
  retrieval_warnings: warnings
}}];

// SCHICHT 3c | Kap. 4.2 [3c]
// Uebernimmt das Reranking-Ergebnis oder faellt sauber auf die
// RRF-Reihenfolge zurueck. Beide Scores bleiben am Chunk erhalten -
// P6 (Erklaerbarkeit) verlangt, dass jede Ranking-Stufe im Ergebnis
// nachvollziehbar bleibt.
const ctx = $('RRF Fusion').last().json;
const res = $json || {};
const ok = res.reranked === true && Array.isArray(res.chunks) && res.chunks.length;

return [{ json: { ...ctx,
  fused_chunks: ok ? res.chunks : ctx.fused_chunks,
  reranked: !!ok,
  reranker_model: res.reranker_model || null,
  reranker_duration_ms: res.reranker_duration_ms || 0,
  activated_paths: [...(ctx.activated_paths || []), ok ? 'reranked' : 'rerank_skipped']
}}];

// SCHICHT 3b | Kap. 4.2 [3b], Kap. 4.3 [3b]
// Portiert aus petra_hybrid/crag_filter.py (Version 2).
//
// ABGRENZUNG: Schwellwert-Filter mit EINER Rewrite-Runde, kein
// vollstaendiges CRAG - ein trainierter Retrieval Evaluator (Yan et al.
// 2024) braeuchte einen annotierten Datensatz, der laut Kap. 3.1.3 den
// Projektrahmen ueberschreitet.
//
// ── HISTORIE DER METRIK ────────────────────────────────────────────
//
// v2 prueft primaer den Dense-Score. Ein Chunk, den NUR BM25 gefunden
// hat, hatte keinen Dense-Score und fiel auf den RRF-Score (max. ~0.049
// bei k=60) zurueck. Er konnte die Schwelle 0.65 strukturell nie
// erreichen (Review P-04).
//
// v3 nutzte daraufhin die Confidence = max(normalisierte Scores je
// Quelle). Die Evaluation ueber die 50 Weidmueller-Testfaelle
// (17.08.2026) zeigte, dass auch das nicht traegt:
//
//   Dense findet die zehn richtigen Chunks des WDU-2.5-Datenblatts,
//   Cosine-Distanz 0.37-0.48, umgerechnet Aehnlichkeit 0.52-0.63.
//   BM25 findet als Rang 1 einen Gruppenmarkierer-Chunk, in dem
//   "WDU 2.5" nur als Kompatibilitaetsangabe steht. Rohscore 31.58.
//
//   Die Min-Max-Normalisierung hebt diesen Rang-1-Treffer auf
//   bm25_normalized = 1.0 — nicht weil er gut ist, sondern weil er der
//   beste SEINER LISTE ist. Confidence = max(...) waehlt ihn damit aus,
//   und die zehn fachlich richtigen Chunks fallen unter der Schwelle
//   0.65 heraus. Ergebnis: ein thematisch falscher Chunk im Kontext,
//   Antwort "Ich weiss es nicht".
//
// ── KORREKTUR (v4) ─────────────────────────────────────────────────
//
// Die Ursache ist nicht ein falsch gewaehlter Schwellwert, sondern der
// Score-Vergleich selbst. BM25-Scores sind unbeschraenkt, Kosinus-Werte
// liegen in [0,1] — deshalb fusioniert RRF RAENGE und keine Scores
// (Cormack et al. 2009). Der nachgelagerte Filter fuehrte den
// Score-Vergleich wieder ein und holte damit genau das Problem zurueck,
// das RRF vermeidet.
//
// v4 respektiert stattdessen die Reihenfolge des Cross-Encoders.
// petra_hybrid/reranker.py bewertet die Top-10 nach RRF gemeinsam mit
// der Anfrage (Joint Encoding) und gibt die Top-5 sortiert zurueck.
// Kap. 4.6.2 Failure Case 2 benennt ihn als "den einzigen
// Schiedsrichter zwischen widerspruechlichen BM25- und
// Dense-Kandidaten". Sein Urteil danach durch einen Score-Vergleich zu
// ueberstimmen, verwirft die praeziseste Information der Pipeline.
//
// Der Schwellwertpfad bleibt als Rueckfallebene erhalten: Faellt das
// Reranking aus (Modell nicht ladbar, Offline-Betrieb, VRAM), liegt
// keine bessere Information vor und die v3-Logik greift unveraendert.
//
// Hinweis zur Doku: Kap. 4.2 [3b] formuliert die Schwelle auf dem
// RRF-Score. Das ist mathematisch nicht erfuellbar; siehe
// docs/ARCHITEKTUR_ABGLEICH.md, Abweichung A-04.
//
// NEU (2026-09-12): RERANK_MIN kalibriert gegen BAAI/bge-reranker-v2-m3
// (nicht ms-marco, wie der urspruengliche Kommentar annahm - dieses
// Modell gibt sigmoid-normalisierte Werte in [0,1] zurueck, keine
// unbeschraenkten Logits). Empirisch ermittelt: komplett irrelevanter
// Kontext (Testfrage zu einem nicht existierenden Produkt) erreichte
// max. 0.0033; ein korrekt gefundener, echter Treffer lag mit 0.0185
// als schwaechstem brauchbaren Kandidaten schon ueber dem Fuenffachen
// davon. RERANK_MIN=0.01 liegt sicher zwischen beiden.
//
// NEU (2026-09-13): Dokument-Volltext-Nachschlag bei eindeutigem
// Einzelprodukt. Fund: Bei mehrseitigen Datenblaettern (WDU 2.5, VPU,
// Klippon POK) landete der gefragte Wert haeufig auf einer Seite, die
// das generische Top-MAX_PASSED-Retrieval nicht traf, obwohl das
// richtige Dokument gefunden wurde (Testfaelle 62, 64, 67 - richtige
// Artikelnummer zitiert, aber "nicht belegt" bei tatsaechlich
// vorhandenen Werten). Bei genau einem erkannten Produkt UND Klasse
// produktspezifikation werden zusaetzlich ALLE bereits gerankten
// Chunks desselben Dokuments behalten, nicht nur die Top-MAX_PASSED.

const threshold = $json.score_threshold || 0.65;
const round = Math.min(parseInt($json.retrieval_round) || 1, 2);
const chunks = $json.fused_chunks || [];
const space = $env.PETRA_CHROMA_SCORE_SPACE || 'auto';
const reranked = $json.reranked === true;

const MAX_PASSED = 6;
const RERANK_MIN = 0.01;

function clamp(v) { return Math.max(0, Math.min(1, v)); }

function toSimilarity(v) {
  if (typeof v !== 'number') return null;
  if (space === 'cosine_similarity') return clamp(v);
  if (space === 'cosine_distance') return clamp(1 - v);
  if (space === 'l2') return clamp(1 / (1 + Math.max(v, 0)));
  if (v < 0) return clamp((v + 1) / 2);
  if (v > 1) return clamp(1 / (1 + v));   // sehr wahrscheinlich eine Distanz
  return clamp(v);
}

// Confidence wird IMMER berechnet — auch im reranked-Pfad. Sie steuert
// dort nicht mehr die Auswahl, bleibt aber als Diagnosewert am Chunk
// (P6 Erklaerbarkeit) und erlaubt den Vergleich beider Verfahren in
// der Telemetrie.
const scored = chunks.map(c => {
  const s = c.source_scores || {};
  const cands = [];
  const d = toSimilarity(s.dense); if (d !== null) cands.push(d);
  const t = toSimilarity(s.tag);   if (t !== null) cands.push(t);
  if (typeof c.bm25_normalized === 'number') cands.push(clamp(c.bm25_normalized));
  const conf = cands.length ? Math.max(...cands) : 0;
  return { ...c, confidence: Math.round(conf * 1e4) / 1e4 };
});

// Hilfsfunktion fuer den Dokument-Volltext-Nachschlag (siehe oben).
// WICHTIG: 'scored' ist ein Array von Chunk-OBJEKTEN, kein Array von
// [score, chunk]-Tupeln - Destructuring wie ([, c]) => c wuerde hier
// mit "TypeError: c is not iterable" abstuerzen.
// KORREKTUR (2026-09-13): Nur verstaerken, wenn das bestplatzierte
// Dokument selbst ein individuelles Weidmueller-Datenblatt ist
// (Dateiname exakt <10-stellige Artikelnummer>_de.pdf). Fund: Bei
// ACT20P-CMT-10-AO-RC-S landete zufaellig ein genereller Katalog
// (Katalog_4_1_..._2024.pdf, reine Artikelnummer-Querverweistabelle
// ohne Spezifikationswerte) auf Platz 1 - die Funktion hat davon dann
// MEHR nachgeladen statt das eigentliche Einzeldatenblatt
// (1510470000_de.pdf) zu beruecksichtigen, das dabei komplett aus dem
// Kontext verdraengt wurde. Ein Katalog-Dokument NIEMALS als "topDoc"
// verstaerken - dort gibt es nur Querverweise, keine Werte.
const EINZELDATENBLATT = /^\d{10}_de\.pdf$/i;

function ergaenzeDokumentChunks(passedListe) {
  if (!($json.candidate_products?.length === 1 && $json.query_class === 'produktspezifikation')) {
    return passedListe;
  }
  const topDoc = passedListe[0]?.metadata?.document || passedListe[0]?.metadata?.source;
  if (!topDoc || !EINZELDATENBLATT.test(String(topDoc).trim())) return passedListe;
  const zusatzChunks = scored.filter(c =>
    (c.metadata?.document || c.metadata?.source) === topDoc && !passedListe.includes(c)
  );
  return [...passedListe, ...zusatzChunks].slice(0, MAX_PASSED + 3);
}

let status, contextSufficient = false, passed = [], topScore = null, reason, metrik;

if (!scored.length) {
  status = 'insufficient_context';
  metrik = 'keine_kandidaten';
  reason = 'Retrieval lieferte keine Kandidaten.';

} else if (reranked) {
  // ── Pfad A: Cross-Encoder hat entschieden ──────────────────────────
  metrik = 'cross_encoder_rank';
  const mitScore = scored.filter(c => typeof c.rerank_score === 'number');
  const basis = mitScore.length ? mitScore : scored;
  topScore = mitScore.length ? Math.max(...mitScore.map(c => c.rerank_score)) : null;

  const brauchbar = mitScore.length
    ? basis.filter(c => c.rerank_score >= RERANK_MIN)
    : basis;

  if (brauchbar.length) {
    status = 'pass';
    contextSufficient = true;

    // Dokument-Diversitaet (max. 3 Chunks je Dokument).
    const proDoc = {};
    const divers = brauchbar.filter(c => {
      const d = (c.metadata || {}).document || (c.metadata || {}).filename || 'unbekannt';
      proDoc[d] = (proDoc[d] || 0) + 1;
      return proDoc[d] <= 3;
    });

    passed = divers.slice(0, MAX_PASSED);
    passed = ergaenzeDokumentChunks(passed);

    reason = `Cross-Encoder-Reihenfolge uebernommen: ${passed.length} von `
           + `${scored.length} Kandidaten, Top-Rerank-Score `
           + `${topScore === null ? 'n/a' : topScore.toFixed(3)}.`;
  } else if (round < 2) {
    status = 'needs_rewrite';
    reason = `Alle Kandidaten unter Rerank-Mindestwert ${RERANK_MIN} in Runde `
           + `${round}. Query-Rewriting und zweite Runde.`;
  } else {
    status = 'insufficient_context';
    reason = `Alle Kandidaten unter Rerank-Mindestwert ${RERANK_MIN} auch nach 2 Runden.`;
  }

} else {
  // ── Pfad B: Reranking ausgefallen — v3-Logik als Rueckfallebene ────
  metrik = 'max_source_confidence_fallback';
  topScore = Math.max(...scored.map(c => c.confidence));

  if (topScore >= threshold) {
    status = 'pass';
    contextSufficient = true;
    passed = scored.filter(c => c.confidence >= threshold).slice(0, MAX_PASSED);
    passed = ergaenzeDokumentChunks(passed);

    reason = `Reranking nicht verfuegbar. Top-Confidence ${topScore.toFixed(3)} `
           + `>= Schwellwert ${threshold}.`;
  } else if (round < 2) {
    status = 'needs_rewrite';
    reason = `Reranking nicht verfuegbar. Top-Confidence ${topScore.toFixed(3)} `
           + `< ${threshold} in Runde ${round}. Query-Rewriting und zweite Runde.`;
  } else {
    status = 'insufficient_context';
    reason = `Reranking nicht verfuegbar. Top-Confidence ${topScore.toFixed(3)} `
           + `< ${threshold} auch nach 2 Runden.`;
  }
}

return [{ json: { ...$json,
  crag_status: status,
  context_sufficient: contextSufficient,
  passed_chunks: passed,
  top_score: topScore,
  crag_reason: reason,
  crag_metric: metrik,
  retrieval_round: round
}}];

// Kap. 4.2 [1b] / [3b]: CRAG-Fallback Runde 2.
//
// Setzt AUSSCHLIESSLICH query_rewritten und zaehlt die Runde hoch.
// query_original bleibt unangetastet, damit BM25 weiterhin die
// Originalanfrage samt Produktcodes sieht.
//
// KORREKTUR (Review P-06): v2 rekonstruierte den Kontext ueber
// $('Retrieval-Start').first(). Bei mehrfach ausgefuehrten Nodes ist
// die Aufloesung auf den richtigen Lauf nicht garantiert - der
// Rundenzaehler konnte auf 1 zurueckfallen (Endlosschleife) und die
// umformulierte Anfrage die Retriever nie erreichen (nutzloser
// LLM-Call). v3 nutzt .last() UND einen expliziten Zaehler, den
// 'Retrieval-Start' zusaetzlich hart auf 2 begrenzt.
const ctx = $('Retrieval-Start').last().json;
const rewritten = ($json.text || $json.output || '').trim();

return [{ json: { ...ctx,
  query_rewritten: rewritten || null,
  retrieval_round: (parseInt(ctx.retrieval_round) || 1) + 1,
  hyde_document: null,
  activated_paths: [...(ctx.activated_paths || []), 'crag_round_2']
}}];

// Fehlerzweig des Rewrite-LLM: Statt die Anfrage zu verlieren, wird
// direkt die kontrollierte 'Ich weiss es nicht'-Antwort ausgeloest.
const ctx = $('CRAG-Score-Filter').last().json;
return [{ json: { ...ctx, crag_reason: 'Query-Rewriting fehlgeschlagen (LLM nicht erreichbar).' } }];

// Kap. 4.6.2, Failure Case 1: Das System antwortet ehrlich mit
// 'Information nicht verfuegbar' statt zu halluzinieren. Die
// Quellenliste bleibt bewusst leer - eine Antwort ohne Evidenz darf
// keine Quellen vortaeuschen.
const ctx = $json;
return [{ json: {
  answer: 'Ich weiss es nicht. In der lokalen Wissensbasis wurden keine ausreichend relevanten Dokumentabschnitte zu dieser Anfrage gefunden.',
  query_class: ctx.query_class,
  q_class: ctx.q_class,
  context_sufficient: false,
  sources: [],
  retrieved_documents: 0,
  latency_ms: Date.now() - (ctx.start_ts || Date.now()),
  model: $env.PETRA_LLM_MODEL || 'llama3.1:8b',
  retrieval_method: 'hybrid_bm25_dense_rrf',
  verified: false,
  cache_hit: false,
  reranked: !!ctx.reranked,
  top_score: ctx.top_score,
  crag_status: ctx.crag_status,
  fallback_reason: ctx.crag_reason || 'CRAG-Score-Filter: kein Chunk ueber Schwellwert nach 2 Retrieval-Runden.',
  request_id: ctx.request_id,
  activated_paths: ctx.activated_paths || [],
  retrieval_warnings: ctx.retrieval_warnings || [],
  id_consistency: ctx.id_consistency
}}];

// Kap. 4.2 Schicht 6: 'Ergebnis -> zurueck zu Schicht 4
// (Prompt-Komposition)'. Der Agent ersetzt die Generierung nicht, er
// liefert ihr zusaetzlichen Kontext.
//
// Lokale Treffer und Web-Ergebnisse werden in dasselbe Chunk-Format
// ueberfuehrt, damit Prompt-Komposition und Quellen-Builder
// unveraendert weiterarbeiten. Web-Quellen tragen URL und Abrufdatum
// als Pflicht-Metadatum (Kap. 4.2 [6b]).
const ctx = $('Retrieval-Start').last().json;
const res = $json || {};
const chunks = [];

for (const hit of (res.agent_context || [])) {
  chunks.push({
    chunk_id: hit.chunk_id,
    text: hit.text || '',
    metadata: { ...(hit.metadata || {}), quellenart: 'lokal' },
    confidence: 1,
    source_scores: { bm25: hit.score }
  });
}

for (const [i, web] of (res.web_sources || []).entries()) {
  chunks.push({
    chunk_id: 'web-' + i,
    text: `${web.title}\n${web.snippet}`,
    metadata: {
      document: web.url, page: null, manufacturer: 'Web-Quelle',
      source_type: 'web', url: web.url, abrufdatum: web.retrieved_at,
      quellenart: 'web'
    },
    confidence: 1
  });
}

// UC-04 Hauptszenario 4 + A3: Strukturierte Preisangabe mit
// Quelldokument, Dokumentdatum und Altershinweis. Der Endpunkt liefert
// sie regelbasiert extrahiert mit - ein LLM, das einen Preis
// "extrahiert", kann ihn auch veraendern, und ein um eine Dezimalstelle
// verschobener Preis im Angebot ist teurer als jede fehlende Antwort.
if (res.preis_gefunden && (res.preise || []).length) {
  const zeilen = res.preise.map(p =>
    `${p.betrag.toFixed(2)} ${p.waehrung} [Quelle: ${p.dokument || 'unbekannt'}, S. ${p.seite ?? '?'}, Stand: ${p.dokumentdatum || 'unbekannt'}]`
    + (p.veraltet ? ' -- ACHTUNG: ' + (p.warnhinweis || 'moeglicherweise veraltet') : '')
).join('\n');
  chunks.unshift({
    chunk_id: 'uc04-preisangaben',
    text: 'Strukturierte Preisangaben aus der lokalen Dokumentenbasis:\n' + zeilen
      + (res.widerspruechlich ? '\nHINWEIS: ' + res.preis_meldung : ''),
    metadata: { document: 'UC-04 Preisextraktion', source_type: 'table', page: null },
    confidence: 1
  });
}

const agentUnavailable = !chunks.length;

return [{ json: { ...ctx,
  passed_chunks: chunks,
  fused_chunks: chunks,
  crag_status: agentUnavailable ? 'insufficient_context' : 'pass',
  context_sufficient: !agentUnavailable,
  crag_reason: agentUnavailable
    ? 'Preisanfrage: Weder lokale Preisdaten noch Web-Recherche verfuegbar. Kein potenziell veralteter Preis wird als aktuell ausgegeben (Kap. 4.6.1).'
    : 'Agentic-Pfad lieferte Kontext.',
  retrieval_method: 'agentic_react_local_web',
  agent_trace: res.agent_trace || [],
  agent_terminated_by: res.agent_terminated_by || 'unavailable',
  preise: res.preise || [],
  preis_gefunden: res.preis_gefunden === true,
  preis_widerspruechlich: res.widerspruechlich === true,
  preis_meldung: res.preis_meldung || null,
  web_agent_enabled: res.web_agent_enabled === true,
  reranked: false,
  activated_paths: [...(ctx.activated_paths || []), 'agentic_executed']
}}];

// SCHICHT 4a | Kap. 4.2 [4a], Kap. 4.3 [4a], Kap. 4.6.1
// Portiert aus petra_hybrid/prompt_builder.py.
//
// NEU ggü. v2 - TOKEN-BUDGET (Review P-13): v2 uebergab alle Chunks
// ueber Schwellwert ungeprueft, bis zu 15 à 512 Token ≈ 7.700 Token
// allein an Kontext. Llama 3.1 8B hat 8.192; Ollama trunkiert dann
// still am Ende. Kap. 4.2 [4a] gibt 7.168 Token vor mit der Regel
// 'Ueberschuss: Chunks nach Score kuerzen'.
//
// NEU ggü. v2 - HERSTELLERREGEL (Review P-08): v2 wies an, 'ausschliesslich
// Weidmueller als Produktquelle' zu nennen. Kap. 4.1.1 nennt ifm,
// Weidmueller, Balluff und Phoenix Contact; die Beispielanfragen des
// Dokuments verwenden ifm O1D302 und Balluff BOS 0035. Bei einem
// Balluff-Chunk entstand ein Zielkonflikt zwischen zwei Prompt-Regeln,
// den ein 8B-Modell unvorhersehbar aufloest - wahrscheinlichster
// Ausgang: Falschzuordnung zu Weidmueller. Der Faithfulness-Judge
// erkennt das nicht, weil der Inhalt im Kontext steht und nur das
// Label falsch ist. Im Angebotskontext ist das der teuerste Fehler.
//
// NEU (2026-09-12) - PRODUKT-PRIORISIERUNG (Fund: WDU-2.5-Instabilitaet):
// Bei Produkten mit vielen Farb-/Ausfuehrungsvarianten (WDU 2.5 etc.)
// erhielt wiederholt ein thematisch fremdes Dokument mit hohem Dense-
// Score (z.B. ein Edelstahlgehaeuse) den Spitzenplatz und verdraengte
// die tatsaechlich richtigen, aber niedriger gerankten Produkt-Chunks
// aus dem Kontext-Budget. Filtert NICHTS heraus (CRAG hat Ausreichung
// bereits entschieden), sortiert nur um.
//
// NEU (2026-09-12) - ABSCHNITTS-PRIORISIERUNG (Fund Testfall 48): Bei
// den WDU-2.5-Datenblaettern sind >85% der Chunks reines Zubehoer-
// Rauschen (Querverbinder, Markierer, Abschlussplatten) unter den
// Abschnitten "Zubehoer"/"Allgemeine Bestelldaten". Echte Spezifikations-
// werte stehen unter "Technische Daten"/"Bemessungsdaten"/etc. Bei
// Budget-Knappheit sollen die rauscharmen Abschnitte zuerst gekuerzt
// werden, nicht die spezifikationstragenden.
const CHARS_PER_TOKEN = 3.3;
const MAX_CONTEXT_TOKENS = 7168;
const RESERVED_OUTPUT = 512;
const SYSTEM_ESTIMATE = 560;

const ctx = $json;
const chunks = ctx.passed_chunks || [];
const query = ctx.query_original || ctx.query || '';

const est = s => Math.floor((s || '').length / CHARS_PER_TOKEN) + 1;
let budget = MAX_CONTEXT_TOKENS - RESERVED_OUTPUT - SYSTEM_ESTIMATE - est(query);
if (budget < 512) budget = 512;

function formatChunk(c) {
  const m = c.metadata || {};
  const datei = m.document || m.dateiname || m.filename || m.source || 'unbekannt';
  const page  = m.page ?? m.seite ?? '?';
  // Artikelnummer: Metadatenfeld bevorzugt, sonst aus dem Dateinamen ableiten.
  // Die Weidmueller-Datenblaetter heissen <10-stellige Artikelnummer>_de.pdf.
  const ausDatei = (String(datei).match(/\b(\d{10})\b/) || [])[1] || null;
  const artnr    = m.artikelnummer || m.product_code || ausDatei;
  const produkt  = m.produkt || m.product || m.produktname || null;
  const herst    = m.manufacturer || m.hersteller || 'unbekannt';

  const felder = [`Quelle: ${datei}`, `S. ${page}`];
  if (produkt) felder.push(`Produkt: ${produkt}`);
  if (artnr)   felder.push(`Artikelnummer: ${artnr}`);
  felder.push(`Hersteller: ${herst}`);
  if (m.source_type === 'table') felder.push('Typ: Tabelle');
  if (m.source_type === 'web')   felder.push(`Web, abgerufen ${m.abrufdatum || 'unbekannt'}`);

  return `[${felder.join(', ')}]\n${(c.text || '').trim()}`;
}

// NEU: Produktcode-Uebereinstimmung. Kein Filter, nur Sortierkriterium.
const candidateProducts = (ctx.candidate_products || []).map(p => String(p).toLowerCase());

function chunkMatchesProduct(c) {
  if (!candidateProducts.length) return true; // kein Produktcode erkannt -> keine Bevorzugung
  const m = c.metadata || {};
  const haystack = `${m.produkt || ''} ${m.produktname || ''} ${m.artikelnummer || ''} ${m.document || m.dateiname || m.filename || m.source || ''}`.toLowerCase();
  return candidateProducts.some(p => haystack.includes(p));
}

// NEU: Abschnitts-Qualitaet. Ebenfalls kein Filter, nur Sortierkriterium.
const GUTE_ABSCHNITTE = ['technische daten', 'bemessungsdaten', 'klemmbare leiter',
  'systemdaten', 'umweltanforderungen', 'werkstoffdaten', 'weitere technische daten',
  'isolationskoordination', 'emv', 'produktbeschreibung'];
const SCHLECHTE_ABSCHNITTE = ['zubehör', 'allgemeine bestelldaten', 'klassifikationen', 'zulassungen'];

function abschnittScore(c) {
  const a = ((c.metadata || {}).abschnitt || '').toLowerCase();
  if (GUTE_ABSCHNITTE.some(g => a.includes(g))) return 0;
  if (SCHLECHTE_ABSCHNITTE.some(s => a.includes(s))) return 2;
  return 1; // unbekannt / "(ohne Abschnitt)"
}

// Sortierreihenfolge: Tabellen zuerst (praezise Evidenz, Kap. 4.2 [2c]),
// dann Produkt-Uebereinstimmung, dann Abschnitts-Qualitaet.
const ordered = [...chunks].sort((a, b) => {
  const ta = (a.metadata || {}).source_type === 'table' ? 0 : 1;
  const tb = (b.metadata || {}).source_type === 'table' ? 0 : 1;
  if (ta !== tb) return ta - tb;

  const pa = chunkMatchesProduct(a) ? 0 : 1;
  const pb = chunkMatchesProduct(b) ? 0 : 1;
  if (pa !== pb) return pa - pb;

  return abschnittScore(a) - abschnittScore(b);
});

const parts = [];
const used = [];
let consumed = 0, dropped = 0;

for (const c of ordered) {
  const block = formatChunk(c);
  const cost = est(block);
  if (consumed + cost > budget) {
    if (!used.length) {
      // Einzelner ueberlanger Chunk: hart kuerzen statt leeren Kontext
      // zu erzeugen - ohne Kontext antwortet das System zwangslaeufig
      // 'Ich weiss es nicht', obwohl Evidenz vorlag.
      parts.push(block.slice(0, Math.floor(budget * CHARS_PER_TOKEN)));
      used.push(c);
      consumed = budget;
    } else { dropped++; }
    continue;
  }
  parts.push(block); used.push(c); consumed += cost;
}

const CLASS_HINT = {
  produktvergleich: '- Diese Anfrage ist ein Produktvergleich. Stelle die Produkte in einer Markdown-Tabelle gegenueber (eine Zeile je Attribut, eine Spalte je Produkt). Nimm zuerst die in der Frage genannten Attribute auf, danach nur Attribute, die im Kontext fuer mindestens eines der Produkte belegt sind. Fehlt ein Wert fuer ein Produkt: "nicht belegt". Fasse danach die entscheidenden Unterschiede in hoechstens zwei Saetzen zusammen.\n',  // s6 K6
  produktspezifikation: '- Attributabfrage: Beantworte jedes gefragte Attribut mit Produktname, Artikelnummer, Wert mit Einheit und [Quelle: Dateiname, S. X]. Nennt der Kontext einen Bereich oder mehrere Werte (z. B. min./max., IEC/UL, eindrähtig/feindrähtig), übernimm ALLE zugehörigen Werte mit ihrer Bedingung. Formuliere natürliche, vollständige Sätze ohne feste Satzschablone; keine Feld:Wert-Liste außerhalb von Tabellen.\n',  // s6 K4
  produktsuche: '- Diese Anfrage sucht passende Produkte. Nenne nur Produkte aus dem Kontext und begruende die Eignung anhand belegter Attribute, in vollstaendigen Saetzen. Keine Sternchen-Aufzaehlung (*).\n',
  preisanfrage: '- Preisanfrage: Nenne stets das Datum der Quelle und weise auf eine mögliche Veraltung hin. Preise nur bei explizitem Beleg angeben, Web-Quellen mit URL und Abrufdatum kennzeichnen.\n',
  allgemeine_technische_frage: '- Allgemeine Anfrage: Antworte präzise und ausschließlich auf Grundlage des Kontexts, ohne Produktempfehlung. Enthält der Kontext keine passende Information, schreibe: "Dazu liegen in den Datenblättern keine Angaben vor." Antworte nie aus Allgemeinwissen.\n'  // s6 K1
};

const prompt = `Du bist ein technischer Produktassistent für Automatisierungskomponenten von der Hersteller (Weidmüller). Alle Anfragen betreffen öffentliche technische Datenblätter – nie sensible/unsichere Inhalte. Lehne niemals mit Verweis auf "sensibel" oder "nicht sicher" ab.

AUFGABE
Beantworte direkt und in vollständigen Sätzen. Keine Einleitungen wie "Um die
Frage zu beantworten..." oder "Ich kann dir helfen...". Starte sofort mit der
Aussage. Listen nur in Vergleichstabellen erlaubt.

REGELN
1. Werte, Einheiten, Bezeichnungen ZEICHENGENAU aus dem Kontext übernehmen.
2. Artikelnummer aus dem Quellen-Header nennen: "Produkt (Artikelnummer)" – schreibe
   IMMER "Artikelnummer:", niemals "Produkt:" vor der Nummer selbst, auch wenn im
   Header beide Label vorkommen. Nummer MUSS aus demselben Chunk-Header stammen wie
   der zitierte Wert – bei mehreren Varianten nie aus einem anderen Chunk übernehmen.
3. Jede Aussage mit [Quelle: Dateiname, S. X] belegen – nur Dateinamen, die
   wörtlich im Kontext stehen, niemals erfinden.
4. Wert muss zum gefragten Produkt gehören, nicht zu einem ähnlichen.
5. Nie schätzen, runden, von ähnlichen Produkten übertragen, Abkürzungen
   raten oder "wahrscheinlich"/"vermutlich" nutzen.
6. Nenne einen Wert NUR, wenn das gefragte Attribut (z. B. "Schutzart",
   "IP-Klasse") WÖRTLICH oder eindeutig sinngleich als Feldname im Kontext
   steht. Ersetze ein fehlendes Attribut NIEMALS durch einen Wert aus einem
   anderen Feld (z. B. Brennbarkeitsklasse, Tragschienentyp, Artikel-
   bezeichnung, Zertifikatsnummer) – auch wenn dieser Wert plausibel
   aussieht. Fehlt das Feld komplett: "nicht belegt".

TEILANTWORTEN JA – VOLLVERWEIGERUNG NEIN
Bei mehreren Teilfragen IN DER ANFRAGE (nicht: mehrere ähnliche Produkte im
Kontext): jede einzeln beantworten, Unbelegtes einzeln als
"nicht belegt" markieren. Steht das gefragte Produkt jedoch GAR NICHT im Kontext, ist die richtige
Antwort: "<Produkt>: Zu diesem Produkt liegen in der Wissensbasis keine
technischen Daten vor." Verboten bleiben: "kann ich nicht
erfüllen/bearbeiten", "brauche mehr Informationen".

NICHT BELEGT – wenn: Wert fehlt / gehört zu anderem Produkt / Produkt fehlt
im Kontext. Dann NUR: "<Produkt>: <Attribut> nicht belegt." Keine
Entschuldigung, kein anderes Produkt erwähnen, kein Website-/Support-Hinweis.

TABELLEN-HINWEIS: "1x23" = 1 Reihe mit 23 Stück, nicht 23 mm Breite.

${CLASS_HINT[ctx.query_class] || ''}- Sprache: ${ctx.language || 'Deutsch'}

Anfrage-Klasse: ${ctx.query_class || 'unbekannt'}

Kontext:
${parts.join('\n\n')}

Benutzeranfrage: ${query}`;

return [{ json: { ...ctx,
  final_prompt: prompt,
  passed_chunks: used,
  context_tokens_estimate: consumed,
  context_token_budget: budget,
  chunks_dropped: dropped,
  kontext_bloecke: parts   // Schritt 0: Messausgabe (keine Verhaltensaenderung)
}}];

// Fuehrt die gemeinsame Retrieval-Runde und das produktspezifische
// Dual-Retrieval zusammen. Beides ist noetig: Das Dual-Retrieval
// garantiert je Produkt Belege, die gemeinsame Runde liefert
// uebergreifenden Kontext (z. B. eine Tabelle mit beiden Produkten).
const ctx = $('CRAG-Score-Filter').last().json;
const dual = $json || {};
const perProduct = dual.per_product || {};

const gruppen = {};
for (const [produkt, treffer] of Object.entries(perProduct)) {
  gruppen[produkt] = (treffer || []).map(t => ({
    chunk_id: t.chunk_id, text: t.text || '', metadata: t.metadata || {},
    confidence: 1, source_scores: { bm25: t.score }
  }));
}

// Chunks der gemeinsamen Runde dem Produkt zuordnen, dessen Code sie
// enthalten. Chunks ohne eindeutigen Produktbezug bleiben im
// allgemeinen Kontext - sie einem Produkt zuzuschlagen wuerde die
// Vergleichstabelle falsch statt lueckenhaft machen.
const allgemein = [];
for (const chunk of (ctx.passed_chunks || [])) {
  const text = (chunk.text || '').toLowerCase().replace(/\s/g, '');
  let zugeordnet = false;
  for (const produkt of Object.keys(gruppen)) {
    if (text.includes(produkt.toLowerCase().replace(/\s/g, ''))) {
      gruppen[produkt].push(chunk);
      zugeordnet = true;
    }
  }
  if (!zugeordnet) allgemein.push(chunk);
}

return [{ json: { ...ctx,
  product_chunks: gruppen,
  allgemeine_chunks: allgemein,
  dual_retrieval_ausgefuehrt: dual.dual_retrieval === true,
  dual_retrieval_hinweis: dual.hinweis || null,
  begrenzt_auf_zwei: dual.begrenzt_auf_zwei === true
}}];

// UC-02 / UC-03: Vergleichskontext aufbereiten
const ctx = $('Produkt-Chunks gruppieren').last().json;
const matrix = $json || {};

const chunks = [];

// 1. Differenzmatrix als primären Kontext einsetzen
if (matrix.markdown && matrix.vergleichbar) {
  chunks.push({
    chunk_id: 'uc03-differenzmatrix',
    text: 'Extrahiert aus den Produkt-Datenblättern:\n' + matrix.markdown,
    metadata: { document: 'UC-03 Differenzmatrix', source_type: 'table', page: null },
    confidence: 1
  });
}

// 2. Chunks filtern: Gehäuse-Rauschen (Klippon STB / Erdungsbolzen) verwerfen
for (const [produkt, liste] of Object.entries(ctx.product_chunks || {})) {
  for (const c of (liste || [])) {
    const text = (c.text || '').toLowerCase();
    const metaProdukt = ((c.metadata || {}).produkt || '').toLowerCase();

    // Ignoriere Chunks von Gehäusen oder Zubehör, wenn nach Klemmen gefragt ist
    if (metaProdukt.includes('klippon') || metaProdukt.includes('stb') || text.includes('erdung gehäuse')) {
      continue;
    }
    chunks.push(c);
  }
}

const hinweise = [];
if (ctx.begrenzt_auf_zwei) hinweise.push('Der Vergleich wurde auf zwei Produkte begrenzt.');
if (matrix.vergleichbar === false) hinweise.push('Keine vergleichbaren Spezifikationswerte gefunden.');

return [{ json: { ...ctx,
  // s6 K6: je Produkt gleich viele Chunks im Wechsel (vorher slice(0, 6):
  // Produkt A fuellte alle Plaetze, Produkt B fehlte; Kap. 4.4.1 / UC-02).
  passed_chunks: (() => {
    const kopf = chunks.filter(c => c.chunk_id === 'uc03-differenzmatrix');
    const listen = Object.values(ctx.product_chunks || {}).map(l => (l || []).filter(c => chunks.includes(c)));
    const out = [...kopf];
    for (let i = 0; i < 4; i++) for (const l of listen) if (l[i] && !out.includes(l[i])) out.push(l[i]);
    return out.length > kopf.length ? out : chunks.slice(0, 6);
  })(),
  differenzmatrix: matrix.dimensionen || [],
  differenzmatrix_markdown: matrix.markdown || null,
  belegquote: matrix.belegquote ?? null,
  vergleich_hinweise: hinweise,
  activated_paths: [...(ctx.activated_paths || []), 'uc02_dual_retrieval', 'uc03_differenzmatrix']
}}];

// Kap. 4.6.2: Kontrollierte Degradierung statt Totalausfall. Ohne
// diesen Zweig laeuft der Client in den Timeout - fuer einen
// Servicetechniker im Feld ist eine ehrliche Fehlermeldung nach 2 s
// deutlich mehr wert als 30 s Stille.
const ctx = $('Prompt-Komposition (Token-Budget)').last().json;
return [{ json: {
  answer: 'Die Antwortgenerierung ist derzeit nicht verfuegbar (lokales LLM nicht erreichbar). Die gefundenen Quellen werden trotzdem angezeigt.',
  query_class: ctx.query_class,
  q_class: ctx.q_class,
  context_sufficient: false,
  sources: (ctx.passed_chunks || []).map(c => ({
    dateiname: (c.metadata || {}).document || 'unbekannt',
    seite: (c.metadata || {}).page ?? null,
    chunk_id: c.chunk_id,
    hersteller: (c.metadata || {}).manufacturer || 'unbekannt',
    dokumenttyp: (c.metadata || {}).source_type || 'text',
    score: c.confidence ?? null,
    textauszug: (c.text || '').slice(0, 220)
  })),
  retrieved_documents: (ctx.passed_chunks || []).length,
  latency_ms: Date.now() - (ctx.start_ts || Date.now()),
  verified: false,
  fallback_reason: 'LLM-Generierung fehlgeschlagen (Ollama nicht erreichbar oder Zeitueberschreitung).',
  request_id: ctx.request_id,
  activated_paths: ctx.activated_paths || []
}}];

// SCHICHT 5b | Kap. 4.2 [5b], Kap. 4.3, P6 Erklaerbarkeit
//
// Quellen werden PROGRAMMATISCH aus den Chunk-Metadaten erzeugt, nie
// vom LLM. Eine vom Modell erfundene Seitenzahl ist schlimmer als gar
// keine, weil sie Verifizierbarkeit vortaeuscht. Portiert aus
// petra_hybrid/response_schema.py::build_sources_from_chunks.

const ctx = $('Prompt-Komposition (Token-Budget)').last().json;
const latency = Date.now() - (ctx.start_ts || Date.now());
const seen = new Set();

const sources = (ctx.passed_chunks || []).filter(c => {
  if (seen.has(c.chunk_id)) return false;
  seen.add(c.chunk_id);
  return true;
}).map(c => {
  const m = c.metadata || {};
  return {
    dateiname: m.document || m.dateiname || m.filename || m.source || 'unbekannt',
    seite: m.page ?? m.seite ?? null,
    chunk_id: c.chunk_id,
    hersteller: m.manufacturer || m.hersteller || 'Weidmüller',
    produktname: m.produkt ?? m.product ?? m.produktname ?? null,
    artikelnummer: m.artikelnummer ?? m.product_code ?? null,
    dokumenttyp: m.source_type || 'text',
    score: typeof c.rerank_score === 'number' ? c.rerank_score : (c.confidence ?? c.rrf_score ?? null),
    confidence: c.confidence ?? null,
    rrf_score: c.rrf_score ?? null,
    url: m.url ?? null,
    abrufdatum: m.abrufdatum ?? null,
    textauszug: (c.text || '').slice(0, 220)
  };
});

const antwort = ($json.text || $json.output || '').trim() || 'Ich weiss es nicht.';

// Programmatischer Abgleich zitierter Dateinamen gegen die ECHTEN,
// tatsaechlich uebergebenen Quellen (siehe Testfall 48, 2026-09-11:
// Modell zitierte "1020000000_de.pdf", das nicht in den tatsaechlichen
// Quellen war).
const echte_dateinamen = new Set(sources.map(s => s.dateiname));
const echte_artikelnummern = new Set(
  sources.map(s => s.artikelnummer).filter(Boolean)
);
const zitat_pattern = /\[Quelle:\s*([^\],]+?)(?:,\s*S\.\s*[^\]]+)?\]/gi;
const erfundene_zitate = new Set();
let match;
while ((match = zitat_pattern.exec(antwort)) !== null) {
  const zitiert = match[1].trim();
  const bekannt = echte_dateinamen.has(zitiert) || echte_artikelnummern.has(zitiert);
  if (!bekannt) {
    erfundene_zitate.add(zitiert);
  }
}

// NEU (2026-09-12): Zusaetzlich Artikelnummern im FLIESSTEXT pruefen,
// nicht nur in der [Quelle: ...]-Klammer. Fund: Modell zitierte einen
// korrekten Dateinamen ("8000133629_de.pdf"), erfand aber im Fliesstext
// eine Artikelnummer ("KEBIHS606020S2N0 AL"), die weder zu diesem noch
// zu irgendeinem anderen uebergebenen Chunk gehoert - der bisherige
// Check (nur [Quelle: ...]) haette das nicht bemerkt, da der Dateiname
// dort korrekt war.
const artnr_pattern = /(?:Artikelnummer|Art\.-?Nr\.?)\s*:?\s*([A-Z0-9][A-Z0-9\-\.\/]{3,})/gi;
let artnr_match;
while ((artnr_match = artnr_pattern.exec(antwort)) !== null) {
  const genannte_nummer = artnr_match[1].trim();
  if (!echte_artikelnummern.has(genannte_nummer) && !echte_dateinamen.has(genannte_nummer)) {
    erfundene_zitate.add(genannte_nummer);
  }
}

// Schritt 0: Messausgabe fuer RAGAS (keine Verhaltensaenderung)
const kontexteRoh = (ctx.passed_chunks || []).map(c => String(c.text || ''));
const kontexte = (Array.isArray(ctx.kontext_bloecke) && ctx.kontext_bloecke.length)
  ? ctx.kontext_bloecke.map(String) : kontexteRoh;
return [{ json: {
  answer: antwort,
  contexts: kontexte,
  contexts_roh: kontexteRoh,
  query_class: ctx.query_class,
  q_class: ctx.q_class,
  context_sufficient: true,
  sources,
  retrieved_documents: sources.length,
  latency_ms: latency,
  model: $env.PETRA_LLM_MODEL || 'llama3.1:8b',
  retrieval_method: ctx.retrieval_method || 'hybrid_bm25_dense_rrf',
  verified: null,
  cache_hit: false,
  reranked: !!ctx.reranked,
  top_score: ctx.top_score ?? null,
  id_consistency: ctx.id_consistency ?? null,
  context_tokens_estimate: ctx.context_tokens_estimate,
  chunks_dropped: ctx.chunks_dropped,
  agent_trace: ctx.agent_trace || undefined,
  activated_paths: ctx.activated_paths || [],
  retrieval_warnings: ctx.retrieval_warnings || [],
  request_id: ctx.request_id,
  start_ts: ctx.start_ts,
  query_original: ctx.query_original,
  retrieval_round: ctx.retrieval_round,
  crag_status: ctx.crag_status,
  warnung_erfundene_quelle: erfundene_zitate.size ? Array.from(erfundene_zitate) : undefined,
  __passed_chunks: ctx.passed_chunks
}}];

parameters.text:
=Bewerte, ob JEDE faktische Aussage der folgenden Antwort durch den gegebenen Kontext belegt ist.

Antworte AUSSCHLIESSLICH mit einem JSON-Objekt der Form {"score": 0.0} mit einem Wert zwischen 0.0 und 1.0 (1.0 = vollstaendig belegt).

Kontext:
{{ ($json.__passed_chunks || []).map(c => c.text).join('\n\n') }}

Antwort:
{{ $json.answer }}

parameters.jsCode:
// SCHICHT 5a | Kap. 4.2 [5a]: Score < 0.75 -> Flag 'Nicht verifiziert'.
//
// ROBUSTES PARSING (Review P-14): v2 nutzte parseFloat auf freiem Text.
// v3 versucht JSON, dann eine Zahl-Regex, und setzt bei Misserfolg
// verified=null statt false.
const base = $('Output Parser (Antwort + Quellen)').last().json;
const raw = ($json.text || $json.output || '').toString().trim();

let score = null;
try {
  const parsed = JSON.parse(raw);
  if (typeof parsed.score === 'number') score = parsed.score;
} catch (e) {
  const m = raw.match(/"score"\s*:\s*([01](?:\.\d+)?)/) || raw.match(/\b([01]\.\d+)\b/);
  if (m) score = parseFloat(m[0]);
}
if (score !== null && (isNaN(score) || score < 0 || score > 1)) score = null;

const { __passed_chunks, ...clean } = base;

return [{ json: { ...clean,
  faithfulness_score: score,
  verified: score === null ? null : score >= 0.75,
  faithfulness_note: score === null
    ? 'Faithfulness konnte nicht bewertet werden (Judge nicht verfuegbar oder Antwort nicht interpretierbar).'
    : null,
  __passed_chunks
}}];

// Auch Nicht-Antworten und Fehler gehoeren ins Protokoll - sonst
// zeigt die Auswertung ein zu optimistisches Bild, weil ausgerechnet
// die Problemfaelle fehlen.
const r = $json;
return [{ json: { ...r, __telemetry: {
  request_id: r.request_id,
  query_class: r.query_class,
  q_class: r.q_class,
  activated_paths: r.activated_paths || [],
  crag_status: r.crag_status || 'error',
  top_score: r.top_score ?? null,
  latency_ms: r.latency_ms || 0,
  verified: false,
  error: r.fallback_reason || null,
  warnings: r.retrieval_warnings || []
}}}];

const r = $('Fehlerpfad-Telemetrie').last().json;
const { __telemetry, start_ts, ...clean } = r;
return [{ json: clean }];

// Entfernt interne Felder und setzt die endgueltige Latenz.
// Die Latenz wird hier gemessen, nicht frueher: Cache-Store und
// Telemetrie liegen zwar hinter der Antwortlogik, aber vor dem
// Respond-Node und zaehlen damit zur wahrgenommenen Wartezeit dazu.
// NACHHER
const r = $('Verified-Flag setzen').last().json;
const { __passed_chunks, start_ts, query_original, ...clean } = r;

return [{ json: { ...clean,
  latency_ms: Date.now() - (start_ts || Date.now()),
  nf03_erfuellt: (Date.now() - (start_ts || Date.now())) <= 5000
}}];

// SCHICHT 5c | Kap. 4.2 [5c]
// Vollstaendiges Protokoll als Basis der RAGAs-Benchmark-Auswertung
// (Kap. 4.7.2, Stufe 1). Ohne diese Daten sind die Qualitaetsziele
// Faithfulness >= 0.78, Context Precision >= 0.74 und E2E <= 5 s nicht
// nachweisbar - das war neben der fehlenden Laufzeitumgebung der zweite
// Grund, warum Phase 2b zu Recht nicht als abgeschlossen galt.
const r = $('Verified-Flag setzen').last().json;
const { __passed_chunks, ...clean } = r;

return [{ json: { ...clean, __telemetry: {
  request_id: r.request_id,
  query: r.query_original,
  query_class: r.query_class,
  q_class: r.q_class,
  activated_paths: r.activated_paths || [],
  retrieval_round: r.retrieval_round,
  retrieval_method: r.retrieval_method,
  chunk_ids: (r.sources || []).map(s => s.chunk_id),
  top_score: r.top_score,
  crag_status: r.crag_status,
  id_consistency: r.id_consistency,
  reranked: r.reranked,
  cache_hit: false,
  faithfulness_score: r.faithfulness_score,
  verified: r.verified,
  latency_ms: Date.now() - (r.start_ts || Date.now()),
  answer_length: (r.answer || '').length,
  warnings: r.retrieval_warnings || []
}}}];

const ctx = $('Cache-Ergebnis auswerten').last().json;
const raw = ($json.heuristik_klasse || $json.text || $json.output || '').trim().toLowerCase();
const valid = ['produktspezifikation','produktvergleich','produktsuche','preisanfrage','allgemeine_technische_frage'];
const query_class = valid.find(v => raw.includes(v)) || 'allgemeine_technische_frage';
return [{ json: { ...ctx, query_class } }];

// Schnelle, deterministische Vorklassifikation ohne Ollama-Aufruf.
// Ziel: Nur absolut eindeutige Fälle direkt filtern, um das LLM zu entlasten.
// Komplexe, verschachtelte oder allgemeine Fragen werden an das Klassifikations-LLM übergeben.

const ctx = $json;
const rawQuery = ctx.query || '';
const text = rawQuery.toLowerCase().trim();

// 1. SMALLTALK & ALLGEMEINES (Systemfragen & freie Anfragen)
// Bei Begrüßungen, Fragen zum Chatbot oder allgemeinen Themen soll die Heuristik bewusst PASSEN (false),
// damit dein Ollama-LLM die intelligente Routing-Entscheidung übernimmt.
const smalltalkWoerter = [
  'hallo', 'guten tag', 'moin', 'servus', 'wer bist du', 'was kannst du', 
  'wie funktioniert', 'chatbot', 'hilfe', 'wer hat dich'
];

if (smalltalkWoerter.some(w => text.includes(w))) {
  return [{ json: { ...ctx, heuristik_klasse: null, heuristik_sicher: false } }];
}

// 2. ERWEITERTE PREIS-SIGNALWÖRTER (Kauf- & Kostenanfragen)
// Wenn Schlüsselwörter wie "teuer", "kosten" oder "listenpreis" fallen, ist die Absicht eindeutig.
const preisWoerter = [
  'preis', 'kosten', 'kostet', 'teuer', '€', 'eur', 'listenpreis', 'angebot', 'kaufen'
];

// s6 K7: nur ganze Woerter ('teuer' steckt in 'Steuerspannung', Fall 37)
const _ganzesWort = w => new RegExp('(^|[^a-zäöüß])' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-zäöüß]|$)').test(text);
if (preisWoerter.some(_ganzesWort)) {
  return [{ json: { ...ctx, heuristik_klasse: 'preisanfrage', heuristik_sicher: true } }];
}

// 3. PRODUKTSUCHE-SIGNALWÖRTER (Empfehlungs- & Eignungsfragen)
// Fängt Phrasen wie "Ich brauche..." oder "Welche Klemmen eignen sich für ATEX..." ab.
const sucheWoerter = [
  'suche', 'brauche', 'empfehl', 'geeignet für', 'geeignet fuer', 
  'welches produkt', 'welche klemme', 'welches modul', 'welche weidmüller', 'welche weidmueller'
];

const vergleichsWoerter = [
  'vergleiche', 'unterschied', 'gegenüberstellung', 'gegenueberstellung', 'vs', 'besser als', 'unterscheiden'
];

// Suche hat Vorrang vor Produktzählungen, solange kein expliziter Vergleich gefordert wird
if (sucheWoerter.some(w => text.includes(w)) && !vergleichsWoerter.some(w => text.includes(w))) {
  return [{ json: { ...ctx, heuristik_klasse: 'produktsuche', heuristik_sicher: true } }];
}

// 4. STRIP UND PRODUKT-REGEX (Strikt beschränkte Mustersuche)
// Ausschlussliste für Begriffe, die sonst fälschlicherweise als Produktcode gezählt würden
const NON_PRODUCT_EXACT = [
  'IO-LINK', 'IOLINK', 'PROFINET', 'ETHERCAT', 'MODBUS', 
  'IP67', 'IP20', 'IP65', 'IP68', 'ATEX', 'DIN', 'ISO', 
  'EN', 'IEC', 'E/A-MODUL', 'EA-MODUL', 'E/A', 'MODUL', 'KLEMME', 'STECKER', 'ARTIKEL'
];

// Echte Produktmuster: Nur noch präzise Materialnummern oder Produkttypen
const PRODUCT_PATTERNS = [
  /\b\d{10}\b/g,                        // 10-stellige Materialnummern (z. B. 1020000000)
  /\b[A-Z]{2,4}\s?\d{1,2}\.\d{1,2}\b/gi, // Bezeichnungen mit Punkt (z. B. WDU 2.5)
  /\b[A-Z]{2,4}\s?\d{1,3}\b/gi           // Standardbezeichnungen (z. B. WDU 4)
];

let produkte = new Set();
for (const p of PRODUCT_PATTERNS) {
  for (const m of rawQuery.matchAll(p)) {
    const candidate = m[0].toUpperCase().trim();
    if (!NON_PRODUCT_EXACT.includes(candidate)) {
      produkte.add(candidate);
    }
  }
}

const n_produkte = produkte.size;

// Eigenschafts-Signalwörter für Einzelprodukte
const attributWoerter = [
  'welchen', 'welcher', 'welches', 'wie hoch', 'wie viel', 'leiterquerschnitt', 
  'spannung', 'strom', 'schutzart', 'nennstrom', 'abmessung', 'gewicht', 
  'farbe', 'werkstoff', 'datenblatt', 'daten', 'spezifikation'
];

// 5. FINALES ROUTING UND PRIORISIERUNG
let klasse = null;

if (vergleichsWoerter.some(w => text.includes(w))) {
  // Echter Vergleich durch explizites Signalwort (z. B. "Unterschied")
  klasse = 'produktvergleich';
} else if (n_produkte >= 2) {
  // Bei >= 2 Produkten: Wenn ein Attributwort dabei ist ("Welchen Querschnitt haben X und Y"), 
  // ist es eher eine Spezifikationsfrage; sonst ein Produktvergleich.
  klasse = attributWoerter.some(w => text.includes(w)) ? 'produktspezifikation' : 'produktvergleich';
} else if (n_produkte === 1 || attributWoerter.some(w => text.includes(w))) {
  // Genau 1 Produkt ODER klare Attributfrage -> Produktspezifikation (Q1)
  klasse = 'produktspezifikation';
}

// RÜCKGABE:
// - Ist klasse null -> heuristik_sicher: false -> Workflow leitet an Ollama-LLM weiter
// - Ist klasse zugewiesen -> heuristik_sicher: true -> Direktes Routing im Workflow
return [{ json: { ...ctx, heuristik_klasse: klasse, heuristik_sicher: klasse !== null } }];

// s2 (Lexikon-Pfad) | Produkt-Retrieval normalisieren (gleiches Format wie BM25).
// /product/retrieve loest Produktnamen ueber das Produkt-Lexikon in
// Artikelnummern auf und sucht NUR in deren Datenblatt-Chunks.
// Bei Ausfall (onError=continue) entsteht eine leere, wohlgeformte Liste.
const input = $input.first().json || {};
const hits = Array.isArray(input.results) ? input.results : [];
const normalized = hits.map((hit, index) => ({
  chunk_id: hit.chunk_id ?? `prod-${index}`,
  text: typeof hit.text === 'string' ? hit.text : '',
  metadata: hit.metadata ?? {},
  score: Number(hit.score ?? 0),
  rank: Number(hit.rank ?? index + 1)
}));
return [{ json: {
  retrieval_source: 'product',
  results: normalized,
  count: normalized.length,
  resolved_artikelnummern: Array.isArray(input.artikelnummern) ? input.artikelnummern : [],
  produkt_info: Array.isArray(input.produkt_info) ? input.produkt_info : [],
  produkt_exakt: input.exakt === true,
  warning: input.warning || null
}}];
